import{_ as e,c as o,o as r,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Настройки логов","description":"","frontmatter":{"title":"Настройки логов"},"headers":[],"relativePath":"ru/logs/settings.md","filePath":"ru/logs/settings.md"}'),d={name:"ru/logs/settings.md"};function a(n,t,g,i,h,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="настроики-логов" tabindex="-1">Настройки логов <a class="header-anchor" href="#настроики-логов" aria-label="Permalink to &quot;Настройки логов&quot;">​</a></h1><p>В <strong>Options → Logs</strong> собраны настройки вкладки <a href="./general.html">Logs</a>. Изменения применяются сразу.</p><hr><h2 id="search-settings" tabindex="-1">Search Settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search Settings&quot;">​</a></h2><p>Режимы поиска вкладки <strong>Logs</strong> по умолчанию:</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Где ищет</th></tr></thead><tbody><tr><td><strong>Search by event name</strong></td><td>Заголовок, компонент, стор, URL (включён по умолчанию)</td></tr><tr><td><strong>Search by key</strong></td><td>Ключи в данных события и пути изменений</td></tr><tr><td><strong>Search by value</strong></td><td>Значения в данных события</td></tr></tbody></table><hr><h2 id="ignore-list" tabindex="-1">Ignore list <a class="header-anchor" href="#ignore-list" aria-label="Permalink to &quot;Ignore list&quot;">​</a></h2><p>Группы событий, добавленные через <strong>Ignore</strong> во вкладке <strong>Logs</strong>. События этих групп не записываются.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Содержимое</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Тип события</td></tr><tr><td><strong>Event</strong></td><td>Ключ группы: запрос (метод и путь), компонент, стор и т.д.</td></tr><tr><td><strong>Added</strong></td><td>Дата добавления правила</td></tr></tbody></table><ul><li><strong>Log again</strong> в меню строки снимает одно правило.</li><li><strong>Log all again</strong> снимает все правила.</li></ul><p>Тот же список доступен через индикатор <strong>ignored</strong> на панели вкладки <strong>Logs</strong>.</p><hr><h2 id="logs-and-limits" tabindex="-1">Logs and limits <a class="header-anchor" href="#logs-and-limits" aria-label="Permalink to &quot;Logs and limits&quot;">​</a></h2><h3 id="logged-events" tabindex="-1">Logged events <a class="header-anchor" href="#logged-events" aria-label="Permalink to &quot;Logged events&quot;">​</a></h3><p>У каждой группы есть чекбокс: снятая группа не логируется совсем, уже записанные события остаются. По умолчанию включены все группы.</p><table tabindex="0"><thead><tr><th>Группа</th><th>События</th></tr></thead><tbody><tr><td><strong>Network</strong></td><td><strong>Send request</strong> и <strong>Receive response</strong></td></tr><tr><td><strong>Props changes</strong></td><td><strong>Change props</strong></td></tr><tr><td><strong>Emits</strong></td><td><strong>Emit</strong></td></tr><tr><td><strong>Pinia changes</strong></td><td><strong>Change store</strong> (после повторной отметки стор начинается с нового <strong>Store snapshot</strong>)</td></tr><tr><td><strong>Store actions</strong></td><td><strong>Store action</strong></td></tr><tr><td><strong>Navigation</strong></td><td><strong>Navigation</strong></td></tr><tr><td><strong>JS errors</strong></td><td><strong>JS error</strong></td></tr></tbody></table><p>Число рядом с чекбоксом показывает, сколько событий группы хранится сейчас.</p><h3 id="data-size" tabindex="-1">Data size <a class="header-anchor" href="#data-size" aria-label="Permalink to &quot;Data size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Диапазон</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Memory budget</strong></td><td>20 МБ</td><td>8 – 1024 МБ</td><td>Общий объём всех событий в буфере (приблизительный размер после сериализации). Сетевая запись, общая для запроса и ответа, и одинаковые тела учитываются один раз</td></tr><tr><td><strong>Limit event size</strong></td><td>выкл.</td><td>—</td><td>Выключено: события хранятся целиком и ничего не обрезается, поэтому экспортированный отчёт содержит полные данные</td></tr><tr><td><strong>Max event size</strong></td><td>512 КБ</td><td>16 – 16 384 КБ</td><td>Только при включённом <strong>Limit event size</strong>: крупные части события (снимки стора, аргументы, результаты) отбрасываются, сетевые тела обрезаются до этого размера</td></tr></tbody></table><p>При достижении бюджета памяти удаляются самые старые события. <strong>Pinia changes</strong> вместо удаления сжимаются в <strong>Store checkpoint</strong>, поэтому у оставшихся изменений сохраняются <strong>Before</strong> / <strong>After</strong>; начальное состояние стора и его checkpoint удаляются последними (см. <a href="./general.html#how-events-are-stored">Как хранятся события</a>). Самое новое событие сохраняется всегда, даже если одно превышает бюджет.</p><p>Полоса под полями показывает текущее использование (<strong>Used X of Y</strong>); выше 90 % она становится оранжевой.</p><p>Значения вне диапазона приводятся к ближайшей границе. <strong>Defaults</strong> восстанавливает все настройки блока.</p><hr><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking {#data-masking}&quot;">​</a></h2><p>Значения маскируются <strong>в момент записи события</strong>, поэтому не попадают ни в интерфейс <strong>Logs</strong>, ни в экспорт.</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Mask sensitive data</strong></td><td>Включает маскирование (включено по умолчанию)</td></tr><tr><td><strong>Mask token-like values in any text</strong></td><td>Маскирует <strong>JWT</strong>, учётные данные <strong>Bearer</strong> / <strong>Basic</strong> и номера карт внутри любой строки</td></tr><tr><td>Список <strong>Key contains</strong></td><td>Ключи объектов, имена заголовков и параметров, содержащие эти фрагменты, маскируются</td></tr></tbody></table><p>Ключи по умолчанию: <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code>, <code>token</code>, <code>authorization</code>, <code>cookie</code>, <code>apikey</code>, <code>sessionid</code>, <code>privatekey</code>, <code>creditcard</code>, <code>cardnumber</code>, <code>cvv</code>, <code>cvc</code>, <code>ssn</code>, <code>otp</code>.</p><p>Сравнение ключей не учитывает регистр и разделители (<code>api_key</code>, <code>api-key</code> и <code>apiKey</code> — одно и то же). Фрагменты из <strong>4 букв и короче</strong> должны совпадать с целым словом, поэтому <code>pwd</code> или <code>otp</code> не маскируют посторонние ключи.</p><p>Свои фрагменты добавляются в поле под списком, удаляются через меню строки. <strong>Default keys</strong> восстанавливает список по умолчанию.</p><p>Замаскированные значения заменяются метками: <code>[MASKED]</code> — для значений чувствительных ключей, <code>[MASKED JWT]</code> и <code>[MASKED CARD]</code> — для токенов и номеров карт, найденных в тексте (номера карт проверяются алгоритмом Луна).</p><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./general.html">Работа с логами</a></li><li><a href="./export.html">Экспорт</a></li><li><a href="/qa-tools/docs/ru/options/settings_management.html">Менеджер настроек</a></li></ul>',34)])])}const b=e(d,[["render",a]]);export{p as __pageData,b as default};
